CREATE MATERIALIZED VIEW mv15 (Qwer DateTime('UTC'), ZxCvbn UInt8, QwertyZx UInt16, KjhgfdPoiuytrZx Int32, zxLkjhPoiuytr UInt8, IuytreZx UInt16, PoiuytrewqHjklZx UInt8, ZxcvbnmlkHjklZx UInt8, QwertyuiopHjklZx UInt16, MnbvcxzaqHjklZx Int32, AsdfghjklzHjklZx Int32, ZxKjh Bool, Zxcvbnmlkj Decimal(38, 3), Mnbvcxzaq Decimal(38, 3))  ENGINE = Null AS WITH __dbt__cte__E_Adserving AS (SELECT toTimeZone(fromUnixTimestamp(toUInt64(coalesce(qwer_tyui, 0) / (1000 * 1000))), 'UTC') AS qwer, coalesce(qwer_asdfghjk_lkjh_fds, 0) AS poiuytr_zx, coalesce(tupleElement(plokij, 'hgfdsaq_zx', 0), 0) AS hgfdsaq_zx, coalesce(tupleElement(plokij, 'asdfghj', 0), 0) AS poi_hjkl, coalesce(tupleElement(plokij, 'poi_uytrew', 0), 0) AS poi_uytrew, coalesce(tupleElement(plokij, 'zxcvbn', 0), 0) AS zxcvbn, coalesce(tupleElement(plokij, 'qwertyuiop_zx', 0), 0) AS qwertyuiop_zx, coalesce(tupleElement(plokij, 'vbnmk_zx', 0), 0) AS vbnmk_zx, coalesce(tupleElement(plokij, 'qwer', 0), 0) AS qwer_plokij, coalesce(tupleElement(tupleElement(kj_hgfd, 'vbnmkjhgf_zxcvb', tuple()), 'xcvbnmk_zx', 0), 0) AS xcvbnmk_zx, coalesce(tupleElement(tupleElement(kj_hgfd, 'vbnmkjhgf_zxcvb', tuple()), 'poiuyt_zx', 0), 0) AS poiuyt_zx_vbnm, coalesce(tupleElement(tupleElement(kj_hgfd, 'vbnmkjhgf_zxcvb', tuple()), 'mnbvcxz_zx', 0), 0) AS mnbvcxz_zx_vbnm, coalesce(tupleElement(kj_hgfd, 'vbnmkjhg_zx', 0), 0) AS vbnmkjhg_zx, coalesce(tupleElement(kj_hgfd, 'asdf_zx', 0), 0) AS asdf_zx, coalesce(tupleElement(kj_hgfd, 'zxcvb_zx', 0), 0) AS zxcvb_zx, coalesce(tupleElement(kj_hgfd, 'iuytre_poiuyt_zx', 0), 0) AS iuytre_poiuyt_zx, coalesce(tupleElement(kj_hgfd, 'zxcvbnm', ''), '') AS zxcvbnm, coalesce(tupleElement(kj_hgfd, 'mnbvcxz_wsxz', 0), 0) AS mnbvcxz_nbvc, coalesce(tupleElement(kj_hgfd, 'asdfghj', 0), 0) AS asdfghj_kj, coalesce(tupleElement(kj_hgfd, 'oiuyt_asdfgh_zx', ''), '') AS oiuyt_asdfgh_zx, coalesce(tupleElement(kj_hgfd, 'oiuyt_asdfgh_mnbvc', ''), '') AS oiuyt_asdfgh_mnbvc, coalesce(tupleElement(kj_hgfd, 'oiuyt_asdfgh_hjkl', ''), '') AS oiuyt_asdfgh_hjkl, coalesce(tupleElement(kj_hgfd, 'oiuyt_asdfgh_poiuytr', ''), '') AS oiuyt_asdfgh_poiuytr, coalesce(tupleElement(kj_hgfd, 'oiuyt_asdfgh_zxcvbnm', 0), 0) AS oiuyt_asdfgh_zxcvbnm, coalesce(tupleElement(kj_hgfd, 'oiuyt_mnbvcx_qwerty', 0), 0) AS oiuyt_mnbvcx_qwerty, coalesce(tupleElement(kj_hgfd, 'oiuyt_zxcvbn_qwerty', 0), 0) AS oiuyt_zxcvbn_qwerty, coalesce(tupleElement(kj_hgfd, 'oiuyt_asdfgh_mnbvcx', ''), '') AS oiuyt_asdfgh_mnbvcx, coalesce(tupleElement(kj_hgfd, 'oiuyt_asdfgh_zxcvbnm_zx', ''), '') AS oiuyt_asdfgh_zxcvbnm_zx, coalesce(tupleElement(kj_hgfd, 'oiuyt_asdfgh_zxcvbnm_wsxz', ''), '') AS oiuyt_asdfgh_zxcvbnm_wsxz, coalesce(tupleElement(kj_hgfd, 'oiuyt_asdfgh_qwertyui_zx', ''), '') AS oiuyt_asdfgh_qwertyui_zx, coalesce(tupleElement(kj_hgfd, 'oiuyt_asdfgh_qwertyui_wsxz', ''), '') AS oiuyt_asdfgh_qwertyui_wsxz, coalesce(tupleElement(kj_hgfd, 'oiuyt_mnbvcxz_asdfgh_zx', ''), '') AS oiuyt_mnbvcxz_asdfgh_zx, coalesce(tupleElement(kj_hgfd, 'oiuyt_poi_zx', ''), '') AS oiuyt_poi_zx, coalesce(tupleElement(kj_hgfd, 'qwerty_zxcvbn_mnbvcx', ''), '') AS qwerty_zxcvbn_mnbvcx, coalesce(tupleElement(kj_hgfd, 'qwerty_zxcvbn_lkjhg', 0), 0) AS qwerty_zxcvbn_lkjhg, coalesce(tupleElement(kj_hgfd, 'qwerty_zxcvbn_lkjhg_xc_zxcvbnm_poiuytre', 0), 0) AS qwerty_zxcvbn_lkjhg_xc_zxcvbnm_poiuytre, coalesce(tupleElement(kj_hgfd, 'poiuytrewq_hjkl', 0), 0) AS poiuytrewq_hjkl, coalesce(tupleElement(kj_hgfd, 'zxcvbnmlk_hjkl', 0), 0) AS zxcvbnmlk_hjkl, coalesce(tupleElement(oiuyt, 'zxcvb_hjkl_zx', 0), 0) AS oiuyt_zxcvb_hjkl_zx, toUInt8(coalesce(tupleElement(tupleElement(kj_hgfd, 'dfghj_lkjhgfds_qwertyu', tuple()), 'zx_poi', false), false)) AS zx_poi, toUInt8(coalesce(tupleElement(tupleElement(kj_hgfd, 'lkjh_poiuytr', tuple()), 'asdfg_zxcvbn', false), false)) AS asdfg_zxcvbn, toUInt8(coalesce(tupleElement(tupleElement(kj_hgfd, 'lkjh_poiuytr', tuple()), 'asdfg_zxcvbn_xc_lkj_poiuytrewq_wsxz', false), false)) AS asdfg_zxcvbn_xc_lkj_poiuytrewq_wsxz, NULL AS zxcvbnm_null, NULL AS cv_poiuytr_zxcvbnm, NULL AS qwerty_zxcvbn_zxcvbnm, NULL AS zxcvbnmkj_dfg_zxcvbnm, NULL AS qwerty_zxcvbn_zxcvbnm_poiuytr_poiuytrew, 1 AS lkjhgfdsa_mnbvcxz_wsxz, coalesce(tupleElement(kj_hgfd, 'zxcvb_mnbvcxz_wsxz', 0), 0) AS zxcvb_mnbvcxz_wsxz, coalesce(tupleElement(kj_hgfd, 'poiuytr_zxcvbnm', 0), 0) AS poiuytr_zxcvbnm, arrayDistinct(coalesce(tupleElement(kj_hgfd, 'oiuyt_asdfgh_cvbn', ''), '')) AS oiuyt_asdfgh_cvbn, arrayMap(x -> coalesce(x, 0), coalesce(tupleElement(tupleElement(kj_hgfd, 'kjhgfd_poiuytr', tuple()), 'kjhgfd_poiuytr_zx', emptyArrayInt32()), emptyArrayInt32())) AS `kjhgfd_poiuytrs.kjhgfd_poiuytr_zx`, arrayMap(x -> coalesce(x, 0), coalesce(tupleElement(tupleElement(kj_hgfd, 'kjhgfd_poiuytr', tuple()), 'kjhgfd_poiuytr_poi_xc_zxcvbnm_lkj', emptyArrayInt32()), emptyArrayInt32())) AS `kjhgfd_poiuytrs.kjhgfd_poiuytr_poi_xc_zxcvbnm_lkj`, arrayMap(x -> coalesce(x, 0), coalesce(tupleElement(tupleElement(kj_hgfd, 'kjhgfd_poiuytr', tuple()), 'kjhgfd_poiuytr_poi_xc_mnbvcxz_lkj', emptyArrayInt32()), emptyArrayInt32())) AS `kjhgfd_poiuytrs.kjhgfd_poiuytr_poi_xc_mnbvcxz_lkj`, arrayMap(x -> coalesce(x, 0), coalesce(tupleElement(tupleElement(kj_hgfd, 'kjhgfd_poiuytr', tuple()), 'kjhgfd_poiuytr_poi_xc_hjkl', emptyArrayInt32()), emptyArrayInt32())) AS `kjhgfd_poiuytrs.kjhgfd_poiuytr_poi_xc_hjkl`, arrayMap(x -> coalesce(x, 0), coalesce(tupleElement(tupleElement(kj_hgfd, 'kjhgfd_poiuytr', tuple()), 'qwerty', emptyArrayInt32()), emptyArrayInt32())) AS `kjhgfd_poiuytrs.qwerty`, arrayMap(x -> toUInt8(coalesce(x, 0)), coalesce(tupleElement(tupleElement(kj_hgfd, 'kjhgfd_poiuytr', tuple()), 'zx_lkjh_poiuytr', emptyArrayInt32()), emptyArrayInt32())) AS `kjhgfd_poiuytrs.zx_lkjh_poiuytr`, arrayMap(x -> toUInt8(coalesce(x, 0)), coalesce(tupleElement(tupleElement(kj_hgfd, 'kjhgfd_poiuytr', tuple()), 'zx_mnbvcxz_poiuytr', emptyArrayInt32()), emptyArrayInt32())) AS `kjhgfd_poiuytrs.zx_mnbvcxz_poiuytr`, arrayMap(x -> coalesce(x, 0), coalesce(tupleElement(tupleElement(kj_hgfd, 'zxcvbnm_poiuytr', tuple()), 'zxcvbnm_poiuytr_zx', emptyArrayInt32()), emptyArrayInt32())) AS `zxcvbnm_poiuytrs.zxcvbnm_poiuytr_zx`, arrayMap(x -> coalesce(x, 0), coalesce(tupleElement(tupleElement(kj_hgfd, 'zxcvbnm_poiuytr', tuple()), 'zxcvbnm_poiuytr_poi_xc_zxcvbnm_lkj', emptyArrayInt32()), emptyArrayInt32())) AS `zxcvbnm_poiuytrs.zxcvbnm_poiuytr_poi_xc_zxcvbnm_lkj`, arrayMap(x -> coalesce(x, 0), coalesce(tupleElement(tupleElement(kj_hgfd, 'zxcvbnm_poiuytr', tuple()), 'zxcvbnm_poiuytr_poi_xc_hjkl', emptyArrayInt32()), emptyArrayInt32())) AS `zxcvbnm_poiuytrs.zxcvbnm_poiuytr_poi_xc_hjkl`, arrayMap(x -> toUInt8(coalesce(x, 0)), coalesce(tupleElement(tupleElement(kj_hgfd, 'zxcvbnm_poiuytr', tuple()), 'zx_asdf_poiuytr', emptyArrayInt32()), emptyArrayInt32())) AS `zxcvbnm_poiuytrs.zx_asdf_poiuytr`, arrayMap(x -> toUInt8(coalesce(x, 0)), coalesce(tupleElement(tupleElement(kj_hgfd, 'zxcvbnm_poiuytr', tuple()), 'zx_mnbvcxz_poiuytr_zxcvbnm', emptyArrayInt32()), emptyArrayInt32())) AS `zxcvbnm_poiuytrs.zx_mnbvcxz_poiuytr_zxcvbnm`, arrayMap(x -> coalesce(x, 0), coalesce(tupleElement(tupleElement(plokij, 'cv_bnml', tuple()), 'poiuytr_zx', emptyArrayInt32()), emptyArrayInt32())) AS `cv_bnmls.poiuytr_zx`, arrayMap(x -> coalesce(x, 0), coalesce(tupleElement(tupleElement(plokij, 'cv_bnml', tuple()), 'poiuytr_qwertyuiop', emptyArrayInt32()), emptyArrayInt32())) AS `cv_bnmls.poiuytr_qwertyuiop`, coalesce(tupleElement(tupleElement(kj_hgfd, 'vbnmkjhgf_zxcvb', tuple()), 'zx_gfds', 0), 0) AS zx_gfds, coalesce(tupleElement(kj_hgfd, 'vbnmkjhg_qwer', 0), 0) AS vbnmkjhg_qwer, coalesce(tupleElement(kj_hgfd, 'mnbvcx_zx', 0), 0) AS mnbvcx_zx, coalesce(tupleElement(tupleElement(kj_hgfd, 'vbnmkjhgf_zxcvb', tuple()), 'zx_kjh', false), false) AS zx_kjh, coalesce(tupleElement(kj_hgfd, 'qwerty_zx', 0), 0) AS qwerty_zx, coalesce(tupleElement(tupleElement(kj_hgfd, 'vbnmkjhgf_zxcvb', tuple()), 'lkjhgfds_asdfgh_zxcvbn', false), false) AS lkjhgfds_asdfgh_zxcvbn, mnbvcxzQwert, zxcvbnmkj_qwer FROM null) SELECT Qwer, 1 AS ZxCvbn, QwertyZx, KjhgfdPoiuytrZx, zxLkjhPoiuytr, IuytreZx, PoiuytrewqHjklZx, ZxcvbnmlkHjklZx, QwertyuiopHjklZx, MnbvcxzaqHjklZx, AsdfghjklzHjklZx, ZxKjh, ((Zxcvbnmlkj - QwertyZxcvbnZxcvbnmlkj) - Gfds) - MnbvcxzGfds AS Zxcvbnmlkj, Mnbvcxzaq FROM (SELECT toStartOfHour(qwer) AS Qwer, toUInt16(poiuytr_zx) AS QwertyZx, poiuytr.kjhgfd_poiuytr_zx AS KjhgfdPoiuytrZx, poiuytr.zx_lkjh_poiuytr AS zxLkjhPoiuytr, toUInt16(iuytre_poiuyt_zx) AS IuytreZx, toUInt8(poiuytrewq_hjkl) AS PoiuytrewqHjklZx, toUInt8(zxcvbnmlk_hjkl) AS ZxcvbnmlkHjklZx, toUInt16(asdfghj_kj) AS QwertyuiopHjklZx, toInt32(0) AS MnbvcxzaqHjklZx, mnbvcx_zx AS AsdfghjklzHjklZx, zx_kjh AS ZxKjh, toDecimal128(sumIf(if(poiuytr.kjhgfd_poiuytr_poi_xc_hjkl = 0, zxcvb_mnbvcxz_wsxz, 1), (qwerty_zx != 0) OR (vbnmkjhg_zx != 0)), 3) AS Zxcvbnmlkj, toDecimal128(0, 3) AS Mnbvcxzaq, sumIf(if(poiuytr.kjhgfd_poiuytr_poi_xc_hjkl = 0, zxcvb_mnbvcxz_wsxz, 1), notEmpty(qwerty_zxcvbn_mnbvcx) AND (vbnmkjhg_zx = 0) AND (qwerty_zx != 0)) AS QwertyZxcvbnZxcvbnmlkj, sumIf(if(poiuytr.kjhgfd_poiuytr_poi_xc_hjkl = 0, zxcvb_mnbvcxz_wsxz, 1), zx_gfds) AS Gfds, sumIf(if(poiuytr.kjhgfd_poiuytr_poi_xc_hjkl = 0, zxcvb_mnbvcxz_wsxz, 1), empty(qwerty_zxcvbn_mnbvcx) AND (vbnmkjhg_zx = 0) AND (qwerty_zx != 0)) AS MnbvcxzGfds FROM __dbt__cte__E_Adserving ARRAY JOIN kjhgfd_poiuytrs AS poiuytr WHERE (poi_uytrew = 1) AND ((zxcvbn = 0) OR ((zxcvbn >= 70) AND (zxcvbn < 90))) AND (zx_kjh = 0) GROUP BY Qwer, QwertyZx, KjhgfdPoiuytrZx, zxLkjhPoiuytr, IuytreZx, PoiuytrewqHjklZx, ZxcvbnmlkHjklZx, QwertyuiopHjklZx, MnbvcxzaqHjklZx, AsdfghjklzHjklZx, ZxKjh);